import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../auth/AuthContext';

const Profile = () => {
  const { user, logout, bookedTickets } = useAuth();
  const navigate = useNavigate();

  const [editMode, setEditMode] = useState(false);
  const [loading, setLoading] = useState(false);

  // DOB max (18+)
  const getMaxDOB = () => {
    const today = new Date();
    today.setFullYear(today.getFullYear() - 18);
    return today.toISOString().split('T')[0];
  };

  const [profile, setProfile] = useState({
    fullName: user?.fullName || '',
    email: user?.email || '',
    devoteeId: `TC${Date.now().toString().slice(-6)}`,
    mobile: '',
    dob: '',
    gender: '',
    addressLine: '',
    city: '',
    state: '',
    country: 'India',
    pincode: ''
  });

  // Load saved profile
  useEffect(() => {
    const saved = localStorage.getItem('templeProfile');
    if (saved) {
      setProfile(JSON.parse(saved));
    }
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setProfile(prev => ({ ...prev, [name]: value }));
  };

  const handleSaveProfile = async () => {
    if (
      !profile.mobile ||
      !profile.dob ||
      !profile.addressLine ||
      !profile.city ||
      !profile.state ||
      !profile.country ||
      !profile.pincode
    ) {
      alert('Please fill all required fields (*)');
      return;
    }

    setLoading(true);
    try {
      localStorage.setItem('templeProfile', JSON.stringify(profile));
      localStorage.setItem(
        'user',
        JSON.stringify({ ...user, fullName: profile.fullName })
      );

      alert('✅ Profile saved successfully 🙏');
      setEditMode(false);
    } catch {
      alert('Save failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-temple-beige to-white">
      {/* Header */}
      <div className="bg-gradient-to-r from-emerald-500 to-teal-600 text-white py-20 text-center">
        <div className="text-5xl mb-3">👤</div>
        <h1 className="text-4xl font-bold">
          {profile.fullName || 'Complete Profile'}
        </h1>
        <p className="opacity-90 mt-2">{profile.email}</p>
        <p className="mt-4 font-mono bg-white/20 inline-block px-6 py-2 rounded-xl">
          Devotee ID: {profile.devoteeId}
        </p>
      </div>

      <div className="max-w-6xl mx-auto px-4 py-12 grid lg:grid-cols-3 gap-8">
        {/* Sidebar */}
        <div className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white p-6 rounded-2xl shadow text-center">
              <div className="text-3xl font-bold text-emerald-600">
                {bookedTickets.length}
              </div>
              <p className="text-sm">Bookings</p>
            </div>
            <div className="bg-white p-6 rounded-2xl shadow text-center">
              <div className="text-2xl font-bold">
                {profile.mobile ? 'Complete' : 'Incomplete'}
              </div>
              <p className="text-sm">Profile</p>
            </div>
          </div>

          <Link
            to="/temples"
            className="block bg-emerald-600 text-white text-center py-4 rounded-2xl font-semibold"
          >
            Book Darshan
          </Link>

          <button
            onClick={handleLogout}
            className="w-full bg-red-500 text-white py-4 rounded-2xl font-bold"
          >
            🚪 Logout
          </button>
        </div>

        {/* Profile Form */}
        <div className="lg:col-span-2 bg-white rounded-3xl p-8 shadow-xl">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-bold">Profile Details</h2>
            <button
              onClick={() => (editMode ? handleSaveProfile() : setEditMode(true))}
              disabled={loading}
              className="bg-emerald-600 text-white px-6 py-2 rounded-xl"
            >
              {editMode ? (loading ? 'Saving...' : 'Save') : 'Edit'}
            </button>
          </div>

          <div className="grid md:grid-cols-2 gap-6">
            {/* Full Name */}
            <input
              type="text"
              name="fullName"
              value={profile.fullName}
              onChange={handleInputChange}
              disabled={!editMode}
              placeholder="Full Name *"
              className="input"
            />

            {/* Mobile */}
            <input
              type="tel"
              name="mobile"
              value={profile.mobile}
              onChange={handleInputChange}
              disabled={!editMode}
              placeholder="Mobile Number *"
              className="input"
            />

            {/* DOB */}
            <input
              type="date"
              name="dob"
              value={profile.dob}
              onChange={handleInputChange}
              disabled={!editMode}
              max={getMaxDOB()}
              className="input"
            />

            {/* Gender */}
            <select
              name="gender"
              value={profile.gender}
              onChange={handleInputChange}
              disabled={!editMode}
              className="input"
            >
              <option value="">Select Gender</option>
              <option>Male</option>
              <option>Female</option>
              <option>Other</option>
            </select>

            {/* Address */}
            <textarea
              name="addressLine"
              value={profile.addressLine}
              onChange={handleInputChange}
              disabled={!editMode}
              placeholder="Home Address *"
              rows="3"
              className="md:col-span-2 input"
            />

            <input
              type="text"
              name="city"
              value={profile.city}
              onChange={handleInputChange}
              disabled={!editMode}
              placeholder="City *"
              className="input"
            />

            <input
              type="text"
              name="state"
              value={profile.state}
              onChange={handleInputChange}
              disabled={!editMode}
              placeholder="State *"
              className="input"
            />

            <input
              type="text"
              name="country"
              value={profile.country}
              disabled
              className="input bg-gray-100"
            />

            <input
              type="text"
              name="pincode"
              value={profile.pincode}
              onChange={handleInputChange}
              disabled={!editMode}
              placeholder="Pincode *"
              className="input"
            />
          </div>

          <p className="text-sm text-gray-500 mt-6">
            * Required fields are mandatory for Darshan booking
          </p>
        </div>
      </div>
    </div>
  );
};

export default Profile;
